        bool is_constrained = triangulation.is_constrained(Triangulation::Edge(current_face, i));

        if (!is_constrained) {
            // Non-constrained edge: propagate the same label
            neighbor_face->info().interior = current_face->info().interior;
            neighbor_face->info().processed = true;
            face_queue.push(neighbor_face);
        } else {
            // Constrained edge: flip the label (odd-even rule)
            neighbor_face->info().interior = !current_face->info().interior;
            neighbor_face->info().processed = true;
            face_queue.push(neighbor_face);
        }
    }
}

// Reset all face labels
for (Triangulation::All_faces_iterator current_face = triangulation.all_faces_begin(); current_face != triangulation.all_faces_end(); ++current_face) {
    current_face->info().processed = false;
    current_face->info().interior = false;
}

// Use BFS to propagate labels using odd-even rule
std::queue<Triangulation::Face_handle> face_queue;

// Find and enqueue all infinite faces as exterior
for (Triangulation::All_faces_iterator current_face = triangulation.all_faces_begin(); current_face != triangulation.all_faces_end(); ++current_face) {
    if (triangulation.is_infinite(current_face)) {
        current_face->info().interior = false;
        current_face->info().processed = true;
        face_queue.push(current_face);
    }
}

// Process faces in BFS order
while (!face_queue.empty()) {
    Triangulation::Face_handle current_face = face_queue.front();
    face_queue.pop();

    // Check all three edges of the current face
    for (int i = 0; i < 3; ++i) {
        Triangulation::Face_handle neighbor_face = current_face->neighbor(i);

        // Skip if neighbor already processed
        if (neighbor_face->info().processed) {
            continue;
        }

        // Check if the edge is constrained
        bool is_constrained = triangulation.is_constrained(Triangulation::Edge(current_face, i));

        if (!is_constrained) {
            // Non-constrained edge: propagate the same label
            neighbor_face->info().interior = current_face->info().interior;
        } else {
            // Constrained edge: flip the label (odd-even rule)
            neighbor_face->info().interior = !current_face->info().interior;
        }

        neighbor_face->info().processed = true;
        face_queue.push(neighbor_face);
    }
}
